FROM LA_RESOURCES T
WHERE T.DEV = 0

    AND T.id IN (
    SELECT DISTINCT T2.RESOURCE_ID FROM LA_ROLE_RESOURCES T2 WHERE T2.AUTHORITY IN
    #{item}
    )


    AND T.id IN
    #{item}

ORDER BY T.RES_LEVEL, T.ORDER_NO

mapper.update:
UPDATE LA_RESOURCES T SET
T.RES_NAME = #{resName},
T.ORDER_NO = #{orderNo}, T.PARENT_ID = #{parentId, jdbcType=VARCHAR}, T.RES_PATH = #{resPath,jdbcType=VARCHAR}, T.METHOD = #{method,jdbcType=VARCHAR}, T.ICON = #{icon,jdbcType=VARCHAR}, T.RES_TYPE = #{resType,jdbcType=INTEGER}, T.RES_LEVEL = #{resLevel,jdbcType=INTEGER}, T.HIDDEN = #{hidden,jdbcType=INTEGER}, T.PARENT_KEYS = #{parentKeys, jdbcType=VARCHAR}, T.RES_MODE = #{resMode,jdbcType=INTEGER}, T.REMARK = #{remark, jdbcType=VARCHAR}, T.KEY_NAME = #{keyName,jdbcType=VARCHAR}, T.KEEP_ALIVE = #{keepAlive,jdbcType=INTEGER}, T.EXPAND = #{expand,jdbcType=VARCHAR}, T.BUSINESS_EXPAND = #{businessExpand,jdbcType=VARCHAR}, T.RES_URL = #{resUrl,jdbcType=VARCHAR} WHERE T.id = #{id}

UPDATE LA_RESOURCES SET ORDER_NO = CASE

    WHEN ID = #{item.id} THEN #{item.orderNo}

END
WHERE id IN

    #{item.id}

UPDATE LA_RESOURCES SET hidden = #{status}
WHERE id IN

    #{item.id}

UPDATE LA_RESOURCES T SET T.RES_LEVEL = CASE

    WHEN id = #{item.id} THEN #{item.resLevel}

END
WHERE id IN

    #{item.id}

UPDATE LA_RESOURCES SET PARENTKEYS = CASE

    WHEN ID = #{item.id} THEN #{item.parentKeys, jdbcType=VARCHAR}

END WHERE id IN

    #{item.id}

UPDATE LA_RESOURCES T SET
    T.ORDER_NO = #{orderNo},
    T.PARENT_ID = #{parentId, jdbcType=VARCHAR},
    T.RES_LEVEL = #{resLevel,jdbcType=INTEGER},
    T.PARENT_KEYS = #{parentKeys, jdbcType=VARCHAR}
WHERE T.id = #{id}

mapper.select:
SELECT PERMISSIONID
FROM LA_API_RESOURCES
WHERE RESOURCEID = #{resourceId}

SELECT DISTINCT MAR.PERMISSIONID AS permissionId, TMP.USERID AS username FROM LA_API_RESOURCES MAR LEFT JOIN ( SELECT USERNAME AS USERID, RESOURCE_ID FROM LA_USER_ROLES MUR JOIN LA_ROLE_RESOURCES MRR ON MUR.AUTHORITY = MRR.AUTHORITY WHERE USERNAME = #{username}
AND MUR.TENANT_ID = #{tenantId}
UNION
SELECT coalesce(#{username},"USERID") USERID, RESOURCE_ID FROM LA_ROLE_RESOURCES WHERE AUTHORITY = CONCAT('ROLE_TENANT@', #{tenantId}) UNION
SELECT AUTHORITY USERID, RESOURCE_ID FROM LA_ROLE_RESOURCES MRR WHERE AUTHORITY = #{username}
AND MRR.TENANT_ID = #{tenantId}
UNION SELECT CLIENTID USERID, RESOURCEID FROM la_client_resources WHERE CLIENTID = #{username} ) TMP ON MAR.RESOURCEID = TMP.RESOURCE_ID WHERE TMP.USERID IS NOT NULL
